import React, { useRef, useEffect } from 'react';

const getRoleColor = (role) => {
    if (role === 'admin') return '#e2e8f0';
    if (role === 'Teacher') return '#c6f6d5';
    if (role === 'Student') return '#fefcbf';
    return '##FFCC01';
};

const ChatRoom = ({ usermessages }) => {
    const messagesEndRef = useRef(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [usermessages]);

    return (
        <div style={{ flexGrow: 1, overflowY: 'auto', padding: '1rem', background: 'white' }}>
            {usermessages.map((msg, index) => (
                <div key={index} style={{
                    marginBottom: '0.5rem',
                    padding: '0.5rem',
                    backgroundColor: getRoleColor(msg.role),
                    borderRadius: '6px'
                }}>
                    <strong>{msg.user}: </strong>{msg.message}
                </div>
            ))}
            <div ref={messagesEndRef} />
        </div>
    );
};

export default ChatRoom;
